package br.com.itbn.sisdent.controller;
import br.com.itbn.sisdent.dto.AppointmentAvailabilityResponse; import br.com.itbn.sisdent.service.AppointmentAvailabilityService; import java.time.*; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/organizations/{organizationId}/appointment-availability") public class AppointmentAvailabilityController { private final AppointmentAvailabilityService service; public AppointmentAvailabilityController(AppointmentAvailabilityService s){service=s;} @GetMapping public List<AppointmentAvailabilityResponse> list(@PathVariable UUID organizationId,@RequestParam UUID clinicUnitId,@RequestParam Instant from,@RequestParam Instant to,@RequestParam(required=false) List<UUID> practitionerIds){return service.list(organizationId,clinicUnitId,from,to,practitionerIds);} }
